pub fn project_check_summary(findings: &[CheckFinding], violations: i64) -> String {
    let mut refused: Vec<String> = vec![];
    let refuted = project_check_count(findings, "NK1207");
    if refuted > 0 { refused.push(format!("{} claim{} shown false", refuted, project_check_plural(refuted))); }
    let types = project_check_count(findings, "NK1") - refuted;
    if types > 0 { refused.push(format!("{} type error{}", types, project_check_plural(types))); }
    let reaching = project_check_count(findings, "NK2503");
    if reaching > 0 { refused.push(format!("{} call{} that can reach a lock", reaching, project_check_plural(reaching))); }
    let undescribed = project_check_count(findings, "NK2504");
    if undescribed > 0 { refused.push(format!("{} Rust crate{} nothing describes", undescribed, project_check_plural(undescribed))); }
    let stale = project_check_count(findings, "NK2505");
    if stale > 0 { refused.push(format!("{} description{} of a crate that has moved", stale, project_check_plural(stale))); }
    let crossings = project_check_count(findings, "NK25") - reaching - undescribed - stale;
    if crossings > 0 { refused.push(format!("{} value{} that may not cross a thread", crossings, project_check_plural(crossings))); }
    let aliases = project_check_count(findings, "NK2302");
    if aliases > 0 { refused.push(format!("{} view{} kept past the call that was given it", aliases, project_check_plural(aliases))); }
    let changed_under = project_check_count(findings, "NK2305");
    if changed_under > 0 { refused.push(format!("{} change{} to data a view still to be used may point into", changed_under, project_check_plural(changed_under))); }
    let tethered = project_check_count(findings, "NK2303");
    if tethered > 0 { refused.push(format!("{} view{} that would keep a buffer alive without a declaration saying so", tethered, project_check_plural(tethered))); }
    let untethered = project_check_count(findings, "NK2304");
    if untethered > 0 { refused.push(format!("{} buffer{} whose views have no one place to live", untethered, project_check_plural(untethered))); }
    let moved = project_check_count(findings, "NK2101");
    if moved > 0 { refused.push(format!("{} value{} a task took with it", moved, project_check_plural(moved))); }
    let together = project_check_count(findings, "NK2104");
    if together > 0 {
        let hole_84 = if together == 1 { "" } else { "es" };
        refused.push(format!("{} branch{} that cannot run beside the others", together, hole_84));
    }
    let raced = project_check_count(findings, "NK2107");
    if raced > 0 { refused.push(format!("{} name{} changed from a lambda that runs on several cores", raced, project_check_plural(raced))); }
    let tasks = project_check_count(findings, "NK21");
    let walked = project_check_count(findings, "NK2702");
    if walked > 0 { refused.push(format!("{} sequence{} walked a second time", walked, project_check_plural(walked))); }
    let pausing = project_check_count(findings, "NK2202");
    let paused_in_a_door = findings.iter().filter(|&f| { f.severity == CheckSeverity::Error && f.code == "NK2202" && f.message.contains("holding a lock") }).count() as i64;
    if paused_in_a_door > 0 { refused.push(format!("{} pause{} with a lock held", paused_in_a_door, project_check_plural(paused_in_a_door))); }
    let pausing = pausing - paused_in_a_door;
    let pauses_forbidden = project_check_count(findings, "NK2209");
    if pauses_forbidden > 0 { refused.push(format!("{} call{} that can pause where nothing may", pauses_forbidden, project_check_plural(pauses_forbidden))); }
    let under_a_lock = project_check_count(findings, "NK2201");
    if under_a_lock > 0 { refused.push(format!("{} read{} of a file with a lock held", under_a_lock, project_check_plural(under_a_lock))); }
    let rules = project_check_count(findings, "NK2605") + project_check_count(findings, "NK2701");
    if rules > 0 { refused.push(format!("{} place{} that can fail without saying so", rules, project_check_plural(rules))); }
    let locks = vec!["NK2203", "NK2204", "NK2205", "NK2207", "NK2208"].iter().map(|code| { project_check_count(findings, code) }).sum::<i64>();
    if locks > 0 { refused.push(format!("{} mistake{} with a lock", locks, project_check_plural(locks))); }
    let others = findings.iter().filter(|&f| { f.severity == CheckSeverity::Error }).count() as i64 - locks - rules - refuted - types - crossings - reaching - undescribed - stale - aliases - changed_under - tethered - untethered - tasks - walked - pausing - paused_in_a_door - pauses_forbidden - under_a_lock;
    if others > 0 { refused.push(format!("{} other error{}", others, project_check_plural(others))); }
    let may_not = violations + pausing;
    if may_not > 0 {
        let hole_118 = if may_not == 1 { "" } else { "s" };
        refused.push(format!("{} call{} a `sync` function may not make", may_not, hole_118));
    }
    refused.join(", ")
}

pub(crate) fn project_check_count(findings: &[CheckFinding], family: &str) -> i64 { findings.iter().filter(|&f| { f.severity == CheckSeverity::Error && f.code.starts_with(family) }).count() as i64 }

pub(crate) fn project_check_plural(n: i64) -> &'static str { if n == 1 { "" } else { "s" } }

pub fn project_check_let_refuted_claims_through(findings: &mut Vec<CheckFinding>, refuted_claims: &str) {
    if refuted_claims != "warn" { return; }
    for finding in findings.iter_mut() {
        if (*finding).code != "NK1207" { continue; }
        (*finding).severity = CheckSeverity::Warning;
        (*finding).notes.push(String::from("`refuted-claims = \"warn\"` lets this build through: the claim is checked when the program runs, and stops it there"));
    }
}

pub fn project_check_let_unproved_claims_through(findings: &mut Vec<CheckFinding>, unproved_claims: &str) {
    if unproved_claims != "warn" { return; }
    for finding in findings.iter_mut() {
        if (*finding).code != "NK1300" { continue; }
        (*finding).severity = CheckSeverity::Warning;
        (*finding).notes.push(String::from("`unproved-claims = \"warn\"` lets this build through: the claim is checked when the program runs, and a false one stops it there"));
    }
}

pub fn project_check_lint_where_nothing_crosses(findings: &mut Vec<CheckFinding>, user_parallelism: &str) {
    if user_parallelism != "no" { return; }
    for finding in findings.iter_mut() {
        if (*finding).code != "NK2501" { continue; }
        (*finding).severity = CheckSeverity::Warning;
        (*finding).notes.push(String::from("`user_parallelism = no` runs nothing you wrote concurrently, so this build does not perform the crossing - it is reported so that the same source still builds at `yes`"));
    }
}

pub fn project_check_locked_proofs(file: &str, why: &str, places: &str, name: &str) -> String { format!("--locked: {} does not hold the prover's answers for these sources ({}).{}\nRun `nikaia build` and commit `{}`.", file, why, places, name) }

pub fn project_check_locked_ledger_missing(path: &str) -> String { format!("--locked, but {} is not there; run without --locked to write it", path) }

pub fn project_check_locked_ledger_changed(path: &str, changed: &str) -> String { format!("--locked: the contracts changed and {} does not say so.\nWhat the build inferred and the ledger does not have:\n{}\nRun without --locked to record it, and read the diff.", path, changed) }

pub trait ProjectCheckHost {
    fn check_against(&self) -> Vec<CheckFinding>;
    fn foreign_check(&self) -> Vec<CheckFinding>;
    fn sync_violations(&self) -> i64;
    fn render_sync_violation(&self, at: i64, path: &str, source: &str) -> String;
    fn render_finding_in(&self, finding: &CheckFinding, path: &str, lines: &[String]) -> String;
    fn in_the_wrapper(&self) -> bool;
    fn eprint(&self, text: &str);
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProjectCheckSaid {
    pub warnings: String,
    pub refused: Option<String>,
}

pub fn project_check_check<H: ProjectCheckHost>(host: &H, path: &str, source: &str, user_parallelism: &str, refuted_claims: &str, unproved_claims: &str, building_a_library: bool) -> ProjectCheckSaid {
    let mut all = host.check_against();
    if building_a_library { all = all.iter().filter(|&finding| { finding.code != "NK1238" }).map(|finding| { finding.clone() }).collect::<Vec<_>>(); }
    all.extend(host.foreign_check());
    all.sort_by_key(|finding| { finding.span.start });
    project_check_lint_where_nothing_crosses(&mut all, user_parallelism);
    project_check_let_refuted_claims_through(&mut all, refuted_claims);
    project_check_let_unproved_claims_through(&mut all, unproved_claims);
    let violations = host.sync_violations();
    if all.is_empty() && violations == 0 { return ProjectCheckSaid { warnings: String::from(""), refused: None }; }
    let in_the_wrapper = host.in_the_wrapper();
    let mut warnings: String = String::from("");
    let lines: Vec<String> = source.split("\n").map(|line| { line.to_string() }).collect::<Vec<_>>();
    for finding in all.iter() {
        let rendered = host.render_finding_in(finding, path, &lines);
        if finding.severity == CheckSeverity::Warning {
            warnings.push_str(&rendered);
            if in_the_wrapper { continue; }
        }
        host.eprint(&rendered);
    }
    if !all.iter().any(|f| { f.severity == CheckSeverity::Error }) && violations == 0 { return ProjectCheckSaid { warnings, refused: None }; }
    for at in 0..violations { host.eprint(&host.render_sync_violation(at, path, source)); }
    ProjectCheckSaid { warnings, refused: Some(project_check_summary(&all, violations)) }
}

pub fn project_check_gained(committed: &Ledger, inferred: &Ledger) -> collections::BTreeMap<String, Vec<String>> {
    let mut out: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for (name, contract) in inferred.functions.iter() {
        let before = match committed.functions.get(name) { Some(__nikaia_value) => __nikaia_value, None => continue };
        let gained: Vec<String> = contract.fails_with.iter().filter(|&error| { !before.fails_with.contains(error) }).map(|x| { x.to_string() }).collect::<Vec<_>>();
        if !gained.is_empty() { out.insert(name.to_string(), gained); }
    }
    out
}

